  const question=requireText(draft.closing_question,'CLOSING_QUESTION');
  if(!/\bif\b/i.test(offer)) throw new Error('CONDITIONAL_OFFER_REQUIRED');
  if(!question.endsWith('?')) throw new Error('CLOSING_QUESTION_REQUIRED');
  const body=`Hi ${first},\n\n${draft.personalization.map(p=>p.text.trim()).join(' ')}\n\n${offer}\n\n${question}`;
  const words=body.split(/\s+/).length;
  if(words<75 || words>110) throw new Error(`WORD_COUNT:${words}`);
  if((body.match(/\?/g)||[]).length!==1) throw new Error('EXACTLY_ONE_QUESTION_REQUIRED');
  const all=subject+'\n'+body;
  if(/[—–]/.test(all)) throw new Error('LONG_DASH');
  if(/\{\{|\}\}|\[(?:insert|name|first|last)|\b(?:undefined|null)\b/i.test(all)) throw new Error('UNRESOLVED_PLACEHOLDER');
  for(const word of BANNED) if(new RegExp(`\\b${word}\\b`,'i').test(all)) throw new Error(`FORBIDDEN_WORD:${word}`);
  if(/\b(?:I'd be happy to|rather than|not (?:simply|just)\b|clinically vetted|legacy|shape the (?:next generation|future)|you're looking for|you are looking for|we reviewed your|as we review clinical expertise)\b/i.test(all)) throw new Error('FORBIDDEN_PHRASE');
  if(/(?:^|[.!?]\s+)(?:Additionally|Furthermore|Moreover|Importantly)\b/im.test(all)) throw new Error('FORBIDDEN_SENTENCE_OPENING');
  if(/\$\s*\d|guarantee(?:d)?|you (?:will|'ll) (?:get|receive|earn)|guaranteed (?:income|returns|board)/i.test(all)) throw new Error('UNAPPROVED_PROMISE_OR_AMOUNT');
